INSERT INTO public.content_sections (id, "createdAt", "updatedAt", title, description, "isActive", data, banner, images, "sectionName") VALUES (18, '2026-08-28 18:55:42.69', '2026-08-28 19:14:47.058', 'Cada rincón guarda una historia.', 'Villa Ana María nació del amor y la memoria. Construida entre 1946 y 1952 por Luis Mario Polo Toral en honor a su pequeña hija Ana María, que falleció con apenas cuatro años y medio, la casa es un testimonio de devoción y ternura. Inspirada en una plumilla traída desde Francia, su estilo francés, combinado con materiales tradicionales españoles y cuencanos, refleja un legado lleno de emotividad. Desde sus primeros días, Villa Ana María fue un hogar cálido, lleno de vida y recuerdos imborrables, que hoy continúa su historia renovada.', true, NULL, '/uploads/cms-raiz-img_1.png', '{}', 'nosotros-historia');
INSERT INTO public.content_sections (id, "createdAt", "updatedAt", title, description, "isActive", data, banner, images, "sectionName") VALUES (19, '2026-08-28 18:55:42.69', '2026-08-28 19:14:47.058', NULL, NULL, true, NULL, '/uploads/cms-raiz-img.webp', '{}', 'nosotros-video');
