INSERT INTO public.content_sections (id, "createdAt", "updatedAt", title, description, "isActive", data, banner, images, "sectionName") VALUES (2, '2026-08-28 18:03:58.479', '2026-08-28 19:08:16.807', 'HABITACIONES CÓMODAS', 'Modernas instalaciones para el descanso perfecto', true, NULL, '/uploads/cms-home-Home2.webp', '{}', 'home-hero-2');
INSERT INTO public.content_sections (id, "createdAt", "updatedAt", title, description, "isActive", data, banner, images, "sectionName") VALUES (3, '2026-08-28 18:03:58.561', '2026-08-28 19:08:16.807', NULL, 'En el corazón de Cuenca, Villa Ana María te ofrece una experiencia única llena de tradición, confort y atención personalizada. Ven a vivir la historia mientras disfrutas de un ambiente acogedor y moderno.', true, NULL, NULL, '{}', 'home-intro');
